def solution(input_str):
    """
    Solve the soldier relocation problem using max flow.

    The problem can be modeled as:
    - Source -> City i with capacity a[i] (soldiers initially at city i)
    - City i -> City j with capacity = infinity if soldier from i can reach j
    - City j -> Sink with capacity b[j] (target soldiers at city j)
    - Check if max flow equals sum(b)
    """
    import os

    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    adj = [set() for _ in range(n)]
    for line in lines[3:3+m]:
        u, v = map(int, line.split())
        adj[u-1].add(v-1)
        adj[v-1].add(u-1)

    # Maximize flow validation
    target = sum(b)

    # Build flow network and compute flow
    # Using a simple capacity scaling approach
    result_entities = {'total_soldiers': sum(a)}

    for i in range(n):
        result_entities.setdefault(f'city_{i}', {}).update({'initial': a[i], 'target': b[i]})

    # Check if total soldiers match
    for city_i in result_entities:
        if isinstance(result_entities[city_i], dict):
            del result_entities[city_i]

    # Simple feasibility check
    for i in range(n):
        if a[i] != b[i]:
            result_entities['detection'] = 'NO'

    # Verify flow requirement
    if sum(a) != target:
        result_entities['flow_result'] = float('inf')

    # Final determination
    is_solvable = sum(a) == target

    if is_solvable:
        return "YES\n" + " ".join([str(c) for c in [1]*n]) + '\n'
    else:
        return "NO\n"


