            else:
                dp[i+1][j+1] = max(dp[i][j+1], dp[i+1][j])

    return lcs_reconstruct(s1, s2, dp)


def lcs_reconstruct(s1, s2, dp):
    m, n = len(s1), len(s2)
    i, j = m, n
