        for i, x in enumerate(a):
            if x not in first:
                first[x] = i

        # Find the longest chain of consecutive distinct values
        # where first occurrences are in non-descending order
        max_chain = 1
        current_chain = 1

        for i in range(1, len(distinct)):
            v1, v2 = distinct[i-1], distinct[i]
            if first[v1] <= first[v2]:
                current_chain += 1
            else:
                max_chain = max(max_chain, current_chain)
                current_chain = 1

        max_chain = max(max_chain, current_chain)
        results.append(str(len(distinct) - max_chain))

