import os
from collections import deque

def solution(problem_input):
    lines = problem_input.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    # Handle edge case where a equals b
    if a == b:
        return "0"

    # Remove duplicate xi values to reduce redundant operations
    x = list(set(x))

    # Distance array from b (index 0 corresponds to value b)
    size = a - b + 1
    dist = [-1] * size

    # BFS initialization
    queue = deque([a])
    dist[a - b] = 0

    while queue:
        v = queue.popleft()

        # Reached the target b
        if v == b:
            return str(dist[0])

        vd = dist[v - b]

        # Option 1: Subtract 1 from current value
        w1 = v - 1
        if w1 >= b and dist[w1 - b] == -1:
            dist[w1 - b] = vd + 1
            queue.append(w1)

        # Option 2: Subtract (v % xi) for each xi
        for xi in x:
            w = v - (v % xi)
            if w >= b and dist[w - b] == -1:
                dist[w - b] = vd + 1
                queue.append(w)

    # Fallback (should not be needed)
    return str(dist[0])
