            continue

        incompatible = []
        for i in range(n):
            ok = False
            if arr[i] % g == 0:
                ok = True
            elif (arr[i] - 1) % g == 0 or (arr[i] + 1) % g == 0:
                ok = True
            else:
                incompatible.append(i)

        if not incompatible:
            cost = sum(b if arr[i] % g != 0 else 0 for i in range(n))
            min_cost = min(min_cost, cost)
            continue

        min_idx, max_idx = min(incompatible), max(incompatible)

        # Try different removal segments covering [min_idx, max_idx]
        for L in range(0, min_idx + 1):
            for R in range(max_idx, min(n, max_idx + 1)):
                removal_cost = (R - L + 1) * a
                change_cost = 0
                valid = True
                for i in range(n):
                    if i < L or i > R:
                        if arr[i] % g == 0:
                            pass
                        elif (arr[i] - 1) % g == 0 or (arr[i] + 1) % g == 0:
                            change_cost += b
                        else:
                            valid = False
                            break
                if valid:
                    min_cost = min(min_cost, removal_cost + change_cost)

    return str(int(min_cost) if min_cost != float('inf') else "0")
